    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .

#################################################################
# Data Properties
#################################################################

:segmentCode a owl:DatatypeProperty ;
    rdfs:label "segment code" ;
    rdfs:comment "The code of a segment (e.g., BGM, NAD)." ;
    rdfs:domain :Segment ;
    rdfs:range xsd:string .

dataValue a owl:DatatypeProperty ;
    rdfs:label "data value" ;
    rdfs:comment "The value of a simple data element." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range xsd:string .

:delimiterValue a owl:DatatypeProperty ;
    rdfs:label "delimiter value" ;
    rdfs:comment "The character value of a delimiter." ;
    rdfs:domain :Delimiter ;
    rdfs:range xsd:string .

:invoiceNumber a owl:DatatypeProperty ;
    rdfs:label "invoice number" ;
    rdfs:comment "The unique identifier of an invoice." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:invoiceDate a owl:DatatypeProperty ;
