] .

# LineItem must have one soldItem and one hasPrice
:LineItem rdfs:subClassOf [
    a owl:Restriction ; owl:onProperty :soldItem ; owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ; owl:onProperty :hasPrice ; owl:cardinality "1"^^xsd:nonNegativeInteger
] .

# Organization must have at least one identifier
:Organization rdfs:subClassOf [
    a owl:Restriction ; owl:onProperty :hasIdentifier ; owl:someValuesFrom :Identifier
] .

# InvoiceSummary must have invoiceAmount
:InvoiceSummary rdfs:subClassOf [
    a owl:Restriction ; owl:onProperty :invoiceAmount ; owl:someValuesFrom xsd:decimal
] .

#################################################################
# Disjointness
