    rdfs:label "involves organization" ;
    rdfs:comment "Relates an invoice message to an involved organization." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an invoice message to a role assignment (reification of organization, role, and context)." ;
